  "CREATE MACRO IF NOT EXISTS \"Skip\"(lst, n) AS CASE  WHEN ((lst IS NULL)) THEN (NULL) WHEN ((n IS NULL)) THEN (lst) WHEN ((typeof(n) NOT IN ('TINYINT', 'SMALLINT', 'INTEGER', 'BIGINT', 'HUGEINT', 'UTINYINT', 'USMALLINT', 'UINTEGER', 'UBIGINT', 'UHUGEINT'))) THEN (\"error\"('CQL Skip count must be Integer')) WHEN ((n < 0)) THEN (lst[1:0]) WHEN ((n >= \"system\".array_length(lst))) THEN (lst[1:0]) ELSE lst[(n + 1):] END",
  "CREATE MACRO IF NOT EXISTS Slice(lst, start := 0, the_end := NULL) AS CASE  WHEN ((lst IS NULL)) THEN (NULL) ELSE (SELECT CASE  WHEN ((_s >= _e)) THEN (lst[1:0]) ELSE list_slice(lst, (_s + 1), _e) END FROM (SELECT least(greatest(CASE  WHEN ((COALESCE(\"start\", 0) < 0)) THEN ((\"system\".array_length(lst) + COALESCE(\"start\", 0))) ELSE COALESCE(\"start\", 0) END, 0), \"system\".array_length(lst)) AS _s, least(greatest(CASE  WHEN ((the_end IS NULL)) THEN (\"system\".array_length(lst)) WHEN ((the_end < 0)) THEN ((\"system\".array_length(lst) + the_end)) ELSE the_end END, 0), \"system\".array_length(lst)) AS _e) AS _slice_t) END",
