  "CREATE MACRO IF NOT EXISTS TailN(lst, n) AS CASE  WHEN ((lst IS NULL)) THEN (NULL) WHEN (((n IS NOT NULL) AND (typeof(n) NOT IN ('TINYINT', 'SMALLINT', 'INTEGER', 'BIGINT', 'HUGEINT', 'UTINYINT', 'USMALLINT', 'UINTEGER', 'UBIGINT', 'UHUGEINT')))) THEN (\"error\"('CQL Tail count must be Integer')) WHEN (((n IS NULL) OR (n <= 0))) THEN (lst[1:0]) ELSE lst[((\"system\".array_length(lst) - least(n, \"system\".array_length(lst))) + 1):] END",
