  "CREATE MACRO IF NOT EXISTS ToDecimal(x) AS CASE  WHEN ((x IS NULL)) THEN (NULL) WHEN ((typeof(x) = 'BOOLEAN')) THEN (CAST(CASE  WHEN (TRY_CAST(x AS BOOLEAN)) THEN (1) ELSE 0 END AS DECIMAL(38, 8))) WHEN (((typeof(x) IN ('TINYINT', 'SMALLINT', 'INTEGER', 'BIGINT', 'FLOAT', 'DOUBLE')) OR starts_with(typeof(x), 'DECIMAL'))) THEN (TRY_CAST(x AS DECIMAL(38, 8))) WHEN (((typeof(x) = 'VARCHAR') AND regexp_full_match(CAST(x AS VARCHAR), '^[+-]?[0-9]+(\\.[0-9]+)?$') AND (TRY_CAST(x AS DECIMAL(38, 8)) IS NOT NULL))) THEN (TRY_CAST(x AS DECIMAL(38, 8))) ELSE NULL END",
  "CREATE MACRO IF NOT EXISTS ToInteger(x) AS CASE  WHEN ((x IS NULL)) THEN (NULL) WHEN ((typeof(x) = 'BOOLEAN')) THEN (CASE  WHEN (TRY_CAST(x AS BOOLEAN)) THEN (1) ELSE 0 END) WHEN ((typeof(x) IN ('TINYINT', 'SMALLINT', 'INTEGER', 'BIGINT'))) THEN (TRY_CAST(x AS INTEGER)) WHEN (((typeof(x) = 'VARCHAR') AND regexp_full_match(CAST(x AS VARCHAR), '^[+-]?[0-9]+$'))) THEN (TRY_CAST(x AS INTEGER)) ELSE NULL END",
  "CREATE MACRO IF NOT EXISTS ToString(x) AS CASE  WHEN ((x IS NULL)) THEN (NULL) WHEN ((ends_with(typeof(x), '[]') OR starts_with(typeof(x), 'STRUCT') OR starts_with(typeof(x), 'MAP') OR (typeof(x) = 'JSON'))) THEN (NULL) WHEN (starts_with(typeof(x), 'DECIMAL')) THEN (CASE  WHEN (ends_with(regexp_replace(CAST(x AS VARCHAR), '0+$', ''), '.')) THEN ((regexp_replace(CAST(x AS VARCHAR), '0+$', '') || '0')) ELSE regexp_replace(CAST(x AS VARCHAR), '0+$', '') END) WHEN (((typeof(x) = 'VARCHAR') AND regexp_full_match(CAST(x AS VARCHAR), '^T[0-9]{2}(:[0-9]{2}(:[0-9]{2}(\\.[0-9]{1,3})?)?)?(Z|[+-][0-9]{2}:[0-9]{2})?$'))) THEN (substr(CAST(x AS VARCHAR), 2)) WHEN (((typeof(x) = 'VARCHAR') AND regexp_full_match(CAST(x AS VARCHAR), '^[0-9]{4}(-[0-9]{2}){0,2}T$'))) THEN (regexp_replace(CAST(x AS VARCHAR), 'T$', '')) WHEN (((typeof(x) = 'VARCHAR') AND regexp_full_match(CAST(x AS VARCHAR), '^[0-9]{4}(-[0-9]{2}){0,2}T[0-9]{2}(:[0-9]{2}){0,2}(\\.[0-9]{1,3})?$') AND regexp_matches(CAST(CURRENT_TIMESTAMP AS VARCHAR), '[+-][0-9]{2}:?[0-9]{0,2}$'))) THEN ((CAST(x AS VARCHAR) || regexp_replace(regexp_replace(CAST(CURRENT_TIMESTAMP AS VARCHAR), '([+-][0-9]{2})$', '\\1:00'), '^.*?([+-][0-9]{2}:[0-9]{2})$', '\\1'))) ELSE CAST(x AS VARCHAR) END",
