  "CREATE MACRO IF NOT EXISTS CQLClinicalCodeEqual(left_code, right_code) AS CASE  WHEN (((cqlclinicalvaluekind(left_code) != 'Code') OR (cqlclinicalvaluekind(right_code) != 'Code'))) THEN (CAST('f' AS BOOLEAN)) WHEN (((json_extract_string(TRY_CAST(CAST(left_code AS VARCHAR) AS \"JSON\"), '$.code') IS NULL) OR (json_extract_string(TRY_CAST(CAST(right_code AS VARCHAR) AS \"JSON\"), '$.code') IS NULL))) THEN (CAST('f' AS BOOLEAN)) WHEN (((cqlclinicalcodesystem(TRY_CAST(CAST(left_code AS VARCHAR) AS \"JSON\")) IS NOT NULL) != (cqlclinicalcodesystem(TRY_CAST(CAST(right_code AS VARCHAR) AS \"JSON\")) IS NOT NULL))) THEN (NULL) WHEN (((json_type(TRY_CAST(CAST(left_code AS VARCHAR) AS \"JSON\"), '$.display') IS NOT NULL) != (json_type(TRY_CAST(CAST(right_code AS VARCHAR) AS \"JSON\"), '$.display') IS NOT NULL))) THEN (NULL) WHEN (((json_type(TRY_CAST(CAST(left_code AS VARCHAR) AS \"JSON\"), '$.version') IS NOT NULL) != (json_type(TRY_CAST(CAST(right_code AS VARCHAR) AS \"JSON\"), '$.version') IS NOT NULL))) THEN (NULL) WHEN ((json_extract_string(TRY_CAST(CAST(left_code AS VARCHAR) AS \"JSON\"), '$.code') IS DISTINCT FROM json_extract_string(TRY_CAST(CAST(right_code AS VARCHAR) AS \"JSON\"), '$.code'))) THEN (CAST('f' AS BOOLEAN)) WHEN ((cqlclinicalcodesystem(TRY_CAST(CAST(left_code AS VARCHAR) AS \"JSON\")) IS DISTINCT FROM cqlclinicalcodesystem(TRY_CAST(CAST(right_code AS VARCHAR) AS \"JSON\")))) THEN (CAST('f' AS BOOLEAN)) WHEN (((json_type(TRY_CAST(CAST(left_code AS VARCHAR) AS \"JSON\"), '$.display') IS NOT NULL) AND (json_extract_string(TRY_CAST(CAST(left_code AS VARCHAR) AS \"JSON\"), '$.display') IS DISTINCT FROM json_extract_string(TRY_CAST(CAST(right_code AS VARCHAR) AS \"JSON\"), '$.display')))) THEN (CAST('f' AS BOOLEAN)) WHEN (((json_type(TRY_CAST(CAST(left_code AS VARCHAR) AS \"JSON\"), '$.version') IS NOT NULL) AND (json_extract_string(TRY_CAST(CAST(left_code AS VARCHAR) AS \"JSON\"), '$.version') IS DISTINCT FROM json_extract_string(TRY_CAST(CAST(right_code AS VARCHAR) AS \"JSON\"), '$.version')))) THEN (CAST('f' AS BOOLEAN)) ELSE CAST('t' AS BOOLEAN) END",
  "CREATE MACRO IF NOT EXISTS CQLClinicalValueHasShape(_clinical_value) AS (cqlclinicalvaluekind(_clinical_value) IS NOT NULL)",
  "CREATE MACRO IF NOT EXISTS CQLIndexOfTemporal(lst, elem) AS CASE  WHEN (((lst IS NULL) OR (elem IS NULL))) THEN (NULL) WHEN (EXISTS(SELECT 1 FROM (SELECT unnest(lst) AS _cql_index_item, generate_subscripts(lst, 1) AS _cql_index_pos) AS _cql_index_items WHERE (CAST(cqllisttemporalelementequal(_cql_index_item, elem) AS BOOLEAN) IS NOT DISTINCT FROM true))) THEN ((SELECT (min(_cql_index_pos) - 1) FROM (SELECT unnest(lst) AS _cql_index_item, generate_subscripts(lst, 1) AS _cql_index_pos) AS _cql_index_items WHERE (CAST(cqllisttemporalelementequal(_cql_index_item, elem) AS BOOLEAN) IS NOT DISTINCT FROM true))) WHEN (EXISTS(SELECT 1 FROM (SELECT unnest(lst) AS _cql_index_item, generate_subscripts(lst, 1) AS _cql_index_pos) AS _cql_index_items WHERE (cqllisttemporalelementequal(_cql_index_item, elem) IS NULL))) THEN (NULL) ELSE -1 END",
  "CREATE MACRO IF NOT EXISTS CQLListContainsTemporalEq(lst, elem) AS CASE  WHEN ((lst IS NULL)) THEN (CAST('f' AS BOOLEAN)) WHEN ((elem IS NULL)) THEN ((\"system\".array_length(lst) != list_count(lst))) WHEN (EXISTS(SELECT 1 FROM (SELECT COALESCE(lst, main.list_value()) AS _cql_contains_l) AS _cql_contains_t , unnest(_cql_contains_t._cql_contains_l) AS _cql_contains_u(_cql_contains_item) WHERE (CAST(cqllisttemporalelementequal(_cql_contains_item, elem) AS BOOLEAN) IS NOT DISTINCT FROM true))) THEN (CAST('t' AS BOOLEAN)) WHEN (EXISTS(SELECT 1 FROM (SELECT COALESCE(lst, main.list_value()) AS _cql_contains_l) AS _cql_contains_t , unnest(_cql_contains_t._cql_contains_l) AS _cql_contains_u(_cql_contains_item) WHERE (cqllisttemporalelementequal(_cql_contains_item, elem) IS NULL))) THEN (NULL) ELSE CAST('f' AS BOOLEAN) END",
  "CREATE MACRO IF NOT EXISTS CQLMessage(source, condition, code, severity, message) AS CASE  WHEN ((COALESCE(condition, CAST('f' AS BOOLEAN)) AND (lower(CAST(severity AS VARCHAR)) = 'error'))) THEN (\"error\"(((COALESCE(CAST(code AS VARCHAR), '') || ': ') || COALESCE(CAST(message AS VARCHAR), '')))) ELSE \"source\" END",
  "CREATE MACRO IF NOT EXISTS CQLNestedListEqElem(_cql_nl_l, _cql_nl_r) AS CASE  WHEN (((_cql_nl_l IS NULL) OR (_cql_nl_r IS NULL))) THEN (NULL) WHEN ((json_array_length(to_json(_cql_nl_l)) != json_array_length(to_json(_cql_nl_r)))) THEN (CAST('f' AS BOOLEAN)) WHEN (list_contains(list_apply(\"range\"(1, (CAST(json_array_length(to_json(_cql_nl_l)) AS BIGINT) + 1)), (lambda i: cqljsoneqelem(TRY_CAST(_cql_nl_l AS \"JSON\"[])[i], TRY_CAST(_cql_nl_r AS \"JSON\"[])[i]))), CAST('f' AS BOOLEAN))) THEN (CAST('f' AS BOOLEAN)) WHEN ((list_count(list_apply(\"range\"(1, (CAST(json_array_length(to_json(_cql_nl_l)) AS BIGINT) + 1)), (lambda i: cqljsoneqelem(TRY_CAST(_cql_nl_l AS \"JSON\"[])[i], TRY_CAST(_cql_nl_r AS \"JSON\"[])[i])))) != json_array_length(to_json(_cql_nl_l)))) THEN (NULL) ELSE CAST('t' AS BOOLEAN) END",
  "CREATE MACRO IF NOT EXISTS CQLNestedListEqTemporal(_cql_nl_l, _cql_nl_r) AS CASE  WHEN (((_cql_nl_l IS NULL) OR (_cql_nl_r IS NULL))) THEN (NULL) WHEN ((json_array_length(to_json(_cql_nl_l)) != json_array_length(to_json(_cql_nl_r)))) THEN (CAST('f' AS BOOLEAN)) WHEN (list_contains(list_apply(\"range\"(1, (CAST(json_array_length(to_json(_cql_nl_l)) AS BIGINT) + 1)), (lambda i: cqljsoneqtemporal(TRY_CAST(_cql_nl_l AS \"JSON\"[])[i], TRY_CAST(_cql_nl_r AS \"JSON\"[])[i]))), CAST('f' AS BOOLEAN))) THEN (CAST('f' AS BOOLEAN)) WHEN ((list_count(list_apply(\"range\"(1, (CAST(json_array_length(to_json(_cql_nl_l)) AS BIGINT) + 1)), (lambda i: cqljsoneqtemporal(TRY_CAST(_cql_nl_l AS \"JSON\"[])[i], TRY_CAST(_cql_nl_r AS \"JSON\"[])[i])))) != json_array_length(to_json(_cql_nl_l)))) THEN (NULL) ELSE CAST('t' AS BOOLEAN) END",
  "CREATE MACRO IF NOT EXISTS GeometricMean(lst) AS CASE  WHEN ((lst IS NULL)) THEN (NULL) WHEN ((NOT ((typeof(lst) IN ('TINYINT[]', 'SMALLINT[]', 'INTEGER[]', 'BIGINT[]', 'HUGEINT[]', 'UTINYINT[]', 'USMALLINT[]', 'UINTEGER[]', 'UBIGINT[]', 'UHUGEINT[]', 'FLOAT[]', 'DOUBLE[]', '\"NULL\"[]')) OR (starts_with(typeof(lst), 'DECIMAL(') AND ends_with(typeof(lst), '[]'))))) THEN (\"error\"('CQL GeometricMean requires List<Decimal> source')) WHEN ((\"system\".array_length(list_filter(list_transform(lst, (lambda _v: TRY_CAST(_v AS \"DOUBLE\"))), (lambda _v: (_v IS NOT NULL)))) = 0)) THEN (NULL) WHEN ((list_min(list_filter(list_transform(lst, (lambda _v: TRY_CAST(_v AS \"DOUBLE\"))), (lambda _v: (_v IS NOT NULL)))) < 0)) THEN (NULL) WHEN ((list_min(list_filter(list_transform(lst, (lambda _v: TRY_CAST(_v AS \"DOUBLE\"))), (lambda _v: (_v IS NOT NULL)))) = 0)) THEN (0.0) ELSE \"system\".exp(list_aggregate(list_transform(list_filter(list_transform(lst, (lambda _v: TRY_CAST(_v AS \"DOUBLE\"))), (lambda _v: (_v IS NOT NULL))), (lambda _v: \"system\".ln(_v))), 'avg')) END",
